<?php

namespace Sapient\Core\Utils;

class JsonParser {
    /**
     * Map of invalid JSON escape sequences commonly generated by LLMs
     * trying to escape Markdown characters.
     */
    private const MARKDOWN_ESCAPES = [
        "\\'" => "'",
        '\$' => '$',
        '\_' => '_',
        '\*' => '*',
        '\`' => '`',
        '\#' => '#',
        '\~' => '~',
        '\|' => '|'
    ];

    /**
     * Extracts and decodes JSON from a string that might contain Markdown or extra text.
     *
     * @param string $content
     * @param bool $sanitize Whether to fix common LLM markdown escapes and invalid JSON tokens (NaN/INF)
     * @return array|null
     */
    public static function parse(string $content, bool $sanitize = true): ?array {
        $content = trim($content);

        if (empty($content)) return null;
        if ($sanitize) {
            // Remove markdown escaping that breaks JSON decoding
            $content = str_replace(
                array_keys(self::MARKDOWN_ESCAPES),
                array_values(self::MARKDOWN_ESCAPES),
                $content
            );

            // Fix unquoted NaN, INF, Infinity which are valid in JS/Python but invalid in strict JSON
            // We wrap them in quotes to preserve the value while making the JSON valid
            $content = preg_replace('/(?<=[,\[:])\s*(NaN|-?INF|-?Infinity)\s*(?=[,\]}])/i', ' "$1" ', $content);
        }

        // 1. Try to find Markdown JSON blocks: ```json ... ```
        if (preg_match('/```json(.*?)```/s', $content, $matches)) {
            $candidate = trim($matches[1]);
            $decoded = json_decode($candidate, true);
            if (is_array($decoded)) return $decoded;
        }

        // 2. Try to find generic code blocks: ``` ... ```
        if (preg_match('/```(.*?)```/s', $content, $matches)) {
            $candidate = trim($matches[1]);
            // If the block starts with 'json' but the previous regex missed it (e.g. malformed)
            if (str_starts_with($candidate, 'json')) {
                $candidate = trim(substr($candidate, 4));
            }
            $decoded = json_decode($candidate, true);
            if (is_array($decoded)) return $decoded;
        }

        // 3. Try to find the first '{' and last '}' or first '[' and last ']'
        $firstBrace = strpos($content, '{');
        $lastBrace = strrpos($content, '}');
        if ($firstBrace !== false && $lastBrace !== false && $lastBrace > $firstBrace) {
            $candidate = substr($content, $firstBrace, $lastBrace - $firstBrace + 1);
            $decoded = json_decode($candidate, true);
            if (is_array($decoded)) return $decoded;
        }

        $firstBracket = strpos($content, '[');
        $lastBracket = strrpos($content, ']');
        if ($firstBracket !== false && $lastBracket !== false && $lastBracket > $firstBracket) {
            $candidate = substr($content, $firstBracket, $lastBracket - $firstBracket + 1);
            $decoded = json_decode($candidate, true);
            if (is_array($decoded)) return $decoded;
        }

        // 4. Final attempt: Raw decode
        $decoded = json_decode($content, true);
        return is_array($decoded) ? $decoded : null;
    }
}
